<?php
require_once __DIR__ . '/_bootstrap.php'; customerPostCsrf(); $message='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'save'; if($action==='delete') customerQuery('DELETE FROM addresses WHERE id=? AND user_id=?',[(int)$_POST['id'],$customerId]); else { $fields=[trim((string)($_POST['label']??'Home')),trim((string)($_POST['address_line']??'')),trim((string)($_POST['city']??'')),trim((string)($_POST['region']??'')),trim((string)($_POST['phone']??''))]; if($fields[1]===''||$fields[2]==='') $message='Address and city are required.'; else customerQuery('INSERT INTO addresses (user_id,label,address_line,city,region,phone) VALUES (?,?,?,?,?,?)',array_merge([$customerId],$fields)); } }
$addresses=customerRows('SELECT id,label,address_line,city,region,phone FROM addresses WHERE user_id=? ORDER BY id DESC',[$customerId]); customerPageStart('Delivery addresses','Addresses'); ?><div class="cw-title"><div><h1>Delivery addresses</h1><p>Save addresses for faster, safer checkout.</p></div></div><?php if($message):?><div class="cw-alert error"><?=e($message)?></div><?php endif;?><div class="cw-grid cw-grid-2"><section class="cw-card"><h2>Add an address</h2><form class="cw-form" method="post"><?=csrfField()?><label>Label<input name="label" placeholder="Home, Office"></label><label>Address<input name="address_line" required></label><div class="cw-grid cw-grid-2"><label>City<input name="city" required></label><label>Region<input name="region"></label></div><label>Delivery phone<input name="phone"></label><button class="cw-btn" type="submit">Save address</button></form></section><section class="cw-card"><h2>Saved addresses</h2><?php if(!$addresses):?><div class="cw-empty">No saved addresses yet.</div><?php else:foreach($addresses as $a):?><article style="padding:14px 0;border-bottom:1px solid #e7edf5"><strong><?=e($a['label'])?></strong><p class="muted"><?=e($a['address_line'])?><br><?=e($a['city'])?> <?=e($a['region'])?><br><?=e($a['phone'])?></p><form method="post"><input type="hidden" name="action" value="delete"><?=csrfField()?><input type="hidden" name="id" value="<?= (int)$a['id']?>"><button class="cw-btn alt" type="submit">Remove</button></form></article><?php endforeach;endif;?></section></div><?php customerPageEnd();?>